-- Membuat Tabel Medical_Procedures untuk melengkapi Dataset Kaggle
CREATE TABLE IF NOT EXISTS Medical_Procedures (
    Procedure_ID VARCHAR(20) PRIMARY KEY,
    patIndex VARCHAR(50), -- Relasi ke dataset Kaggle
    Procedure_Date DATE,
    Procedure_Code VARCHAR(20),
    Procedure_Category VARCHAR(50),
    Procedure_Description VARCHAR(255),
    Cost DECIMAL(10, 2)
);

